DROP TABLE IF EXISTS `tbd_products_categories`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `tbd_products_categories` (
  `product_Id` int unsigned NOT NULL,
  `category_Id` int unsigned NOT NULL,
  `status` bit(1) NOT NULL,
  `creation_date` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `last_update` datetime DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`category_Id`,`product_Id`),
  KEY `fk_products_1_idx` (`product_Id`),
  CONSTRAINT `fk_category_1` FOREIGN KEY (`category_Id`) REFERENCES `tbc_categories` (`ID`),
  CONSTRAINT `fk_products_1` FOREIGN KEY (`product_Id`) REFERENCES `tb_products` (`ID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
